from datetime import datetime

class EmailClient:
    EMAIL_STATE_UNREAD = "unread"
    EMAIL_STATE_READ = "read"
    EMPTY_ADDR_ERROR = "Address cannot be empty"

    def __init__(self, addr, capacity) -> None:
        self._addr = addr
        self.capacity = capacity
        self._inbox = []

    @property
    def addr(self):
        return self._addr

    @addr.setter
    def addr(self, value):
        if not value:
            raise ValueError(self.EMPTY_ADDR_ERROR)
        self._addr = value

    def send_to(self, recv, content, size):
        if self._is_within_capacity(recv, size):
            email = self._create_email(recv, content, size)
            recv.add_email(email)
            return True
        self.clear_inbox(size)
        return False

    def _is_within_capacity(self, recv, size):
        return not recv.is_full_with_one_more_email(size)

    def _create_email(self, recv, content, size):
        return {
            "sender": self.addr,
            "receiver": recv.addr,
            "content": content,
            "size": size,
            "time": self._current_timestamp(),
            "state": self.EMAIL_STATE_UNREAD
        }

    def _current_timestamp(self):
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    def add_email(self, email):
        self._inbox.append(email)

    def fetch(self):
        return self._find_and_mark_first_unread_email()

    def _find_and_mark_first_unread_email(self):
        for email in self._inbox:
            if email['state'] == self.EMAIL_STATE_UNREAD:
                email['state'] = self.EMAIL_STATE_READ
                return email
        return None

    def is_full_with_one_more_email(self, size):
        return self.get_occupied_size() + size > self.capacity

    def get_occupied_size(self):
        return sum(email["size"] for email in self._inbox)

    def clear_inbox(self, size):
        if not self.addr:
            return
        self._clear_inbox_until_freed(size)

    def _clear_inbox_until_freed(self, size):
        freed_space = 0
        while freed_space < size and self._inbox:
            email = self._inbox[0]
            freed_space += email['size']
            self._inbox.pop(0)
